from dispatchiq.helpers import route, route_cost, travel_min, drop_until_feasible


def replan(state):
    jobs = state["jobs"]
    techs = state["techs"]
    healthy = [t for t in techs if not t["sick"]]
    tech_by_id = {t["id"]: t for t in techs}
    healthy_ids = {t["id"] for t in healthy}

    full_plan = {t["id"]: [] for t in techs}
    if not healthy:
        return full_plan

    route_cache = {}
    cost_cache = {}
    INF = float('inf')

    def R(tech, seq):
        key = (tech["id"], tuple(seq))
        v = route_cache.get(key)
        if v is None:
            v = route(state, tech, seq)
            route_cache[key] = v
        return v

    def C(tech, seq):
        key = (tech["id"], tuple(seq))
        v = cost_cache.get(key)
        if v is None:
            v = route_cost(state, tech, seq)
            cost_cache[key] = v
        return v

    def churn(tech, jid):
        mt = jobs[jid].get("morning_tech")
        if mt in healthy_ids and mt != tech["id"]:
            return 20
        return 0

    def total_cost(tech, seq):
        c = C(tech, seq)
        for jid in seq:
            c += churn(tech, jid)
        return c

    def latest_key(j):
        l = jobs[j]["latest"]
        return l if l is not None else INF

    def optimize_seq(tech, job_ids):
        job_ids = [j for j in job_ids if jobs[j]["skill"] in tech["skills"]]
        if not job_ids:
            return []
        if len(job_ids) == 1:
            return list(job_ids)
        n = len(job_ids)

        starts = [
            sorted(job_ids, key=lambda j: (jobs[j]["earliest"], latest_key(j), j)),
            sorted(job_ids, key=lambda j: (latest_key(j), jobs[j]["earliest"], j)),
            sorted(job_ids, key=lambda j: (-jobs[j]["priority"], latest_key(j), j)),
        ]
        greedy = []
        rem = list(job_ids)
        while rem:
            best = None
            best_c = INF
            for jid in rem:
                for pos in range(len(greedy) + 1):
                    cand = greedy[:pos] + [jid] + greedy[pos:]
                    c = C(tech, cand)
                    if c < best_c:
                        best_c = c
                        best = (jid, pos)
            jid, pos = best
            greedy = greedy[:pos] + [jid] + greedy[pos:]
            rem.remove(jid)
        starts.append(greedy)
        starts.append(list(job_ids))

        best_seq = None
        best_cost = INF
        for s in starts:
            seq = list(s)
            improved = True
            iters = 0
            while improved and iters < 25:
                iters += 1
                improved = False
                cur = C(tech, seq)
                done = False
                for i in range(n - 1):
                    for j in range(i + 1, n):
                        ns = seq[:i] + seq[i:j + 1][::-1] + seq[j + 1:]
                        c = C(tech, ns)
                        if c < cur - 1e-9:
                            seq = ns
                            cur = c
                            improved = True
                            done = True
                            break
                    if done:
                        break
                if improved:
                    continue
                done = False
                for i in range(n):
                    for j in range(n):
                        if i == j:
                            continue
                        tmp = seq[:i] + seq[i + 1:]
                        ns = tmp[:j] + [seq[i]] + tmp[j:]
                        if ns == seq:
                            continue
                        c = C(tech, ns)
                        if c < cur - 1e-9:
                            seq = ns
                            cur = c
                            improved = True
                            done = True
                            break
                    if done:
                        break
            c = C(tech, seq)
            if c < best_cost:
                best_cost = c
                best_seq = seq
        return best_seq

    def custom_drop_to_keep(tech, seq, must_keep):
        if R(tech, seq)["feasible"]:
            return list(seq), []
        current = list(seq)
        dropped = []
        while True:
            r = R(tech, current)
            if r["feasible"]:
                return current, dropped
            candidates = [jid for jid in current
                          if jid != must_keep and not jobs[jid]["emergency"]]
            if not candidates:
                return None, None
            best_single = None
            best_single_cost = INF
            for jid in candidates:
                idx = current.index(jid)
                cand = current[:idx] + current[idx + 1:]
                if R(tech, cand)["feasible"]:
                    cost = C(tech, cand) + sum(
                        150 * jobs[d]["priority"] for d in dropped + [jid]
                    )
                    if cost < best_single_cost:
                        best_single_cost = cost
                        best_single = (cand, dropped + [jid])
            if best_single is not None:
                return best_single
            best_score = -1
            best_jid = None
            current_end = r["end"]
            for jid in candidates:
                idx = current.index(jid)
                cand = current[:idx] + current[idx + 1:]
                new_end = R(tech, cand)["end"]
                reduction = current_end - new_end
                score = reduction / (jobs[jid]["priority"] + 0.1)
                if score > best_score:
                    best_score = score
                    best_jid = jid
            if best_jid is None:
                return None, None
            idx = current.index(best_jid)
            current = current[:idx] + current[idx + 1:]
            dropped.append(best_jid)

    # ---------- initial plan ----------
    plan = {}
    unassigned = []
    for t in healthy:
        seq = optimize_seq(t, list(t["remaining"]))
        if seq and not R(t, seq)["feasible"]:
            kept, dropped = drop_until_feasible(state, t, seq)
            seq = list(kept)
            for d in dropped:
                if d not in unassigned:
                    unassigned.append(d)
        plan[t["id"]] = seq

    assigned = set()
    for s in plan.values():
        assigned.update(s)
    for jid in jobs:
        if jid not in assigned and jid not in unassigned:
            unassigned.append(jid)

    def sort_unassigned():
        unassigned.sort(key=lambda jid: (
            0 if jobs[jid]["emergency"] else 1,
            -jobs[jid]["priority"],
            jobs[jid]["earliest"],
            jid
        ))

    def best_insertion(jid):
        job = jobs[jid]
        best = None
        best_delta = INF
        for t in healthy:
            if job["skill"] not in t["skills"]:
                continue
            seq = plan[t["id"]]
            old_cost = total_cost(t, seq)
            for pos in range(len(seq) + 1):
                cand = seq[:pos] + [jid] + seq[pos:]
                if R(t, cand)["feasible"]:
                    delta = total_cost(t, cand) - old_cost
                    if delta < best_delta:
                        best_delta = delta
                        best = (t["id"], cand, [])
                else:
                    kept, dropped = custom_drop_to_keep(t, cand, jid)
                    if kept is None:
                        continue
                    extra = 0
                    for d in dropped:
                        extra += 150 * jobs[d]["priority"]
                    delta = total_cost(t, kept) + extra - old_cost
                    if delta < best_delta:
                        best_delta = delta
                        best = (t["id"], kept, dropped)
        return best, best_delta

    def apply_insertion(jid, move):
        tid, seq, dropped = move
        t = tech_by_id[tid]
        new_seq = optimize_seq(t, seq)
        if new_seq and not R(t, new_seq)["feasible"]:
            kept, extra = custom_drop_to_keep(t, new_seq, jid)
            if kept is None:
                return False
            new_seq = kept
            dropped = list(dropped) + list(extra)
        if jid not in new_seq:
            return False
        plan[tid] = new_seq
        if jid in unassigned:
            unassigned.remove(jid)
        for d in dropped:
            if d != jid and d not in unassigned:
                unassigned.append(d)
        return True

    def insert_pass():
        changed = False
        sort_unassigned()
        for jid in list(unassigned):
            job = jobs[jid]
            move, delta = best_insertion(jid)
            if move is None:
                continue
            threshold = 150 * job["priority"]
            if job["emergency"] or delta < threshold - 1e-9:
                if apply_insertion(jid, move):
                    changed = True
        return changed

    # ---------- regret insertion with depth-2 ejection chain ----------
    def best_reinsert_delta(e, exclude_tid=None):
        job = jobs[e]
        best = None
        for t in healthy:
            if t["id"] == exclude_tid:
                continue
            if job["skill"] not in t["skills"]:
                continue
            seq = plan[t["id"]]
            old_cost = total_cost(t, seq)
            for pos in range(len(seq) + 1):
                cand = seq[:pos] + [e] + seq[pos:]
                if not R(t, cand)["feasible"]:
                    continue
                delta = total_cost(t, cand) - old_cost
                if best is None or delta < best[0]:
                    best = (delta, t["id"], cand)
        return best

    def try_chain(jid, pen_jid):
        """Depth-2 ejection chain: eject a low-priority non-emergency job e
        from the tech that would best host jid, then reinsert e elsewhere."""
        job = jobs[jid]
        best_chain = None
        best_total = -1e-9
        for t in healthy:
            if job["skill"] not in t["skills"]:
                continue
            seq = plan[t["id"]]
            if not seq:
                continue
            old_t = total_cost(t, seq)
            eject_cands = [e for e in seq if not jobs[e]["emergency"]]
            eject_cands.sort(key=lambda e: (jobs[e]["priority"], e))
            for e in eject_cands:
                seq_wo_e = [x for x in seq if x != e]
                local_best = None
                for pos in range(len(seq_wo_e) + 1):
                    cand = seq_wo_e[:pos] + [jid] + seq_wo_e[pos:]
                    if not R(t, cand)["feasible"]:
                        continue
                    d = total_cost(t, cand) - old_t
                    if local_best is None or d < local_best[0]:
                        local_best = (d, cand)
                if local_best is None:
                    continue
                d_jid, cand_jid = local_best
                re = best_reinsert_delta(e, exclude_tid=t["id"])
                if re is None:
                    e_cost = 150 * jobs[e]["priority"]
                    total = d_jid - pen_jid + e_cost
                    if total < best_total:
                        best_total = total
                        best_chain = (t["id"], cand_jid, e, None)
                else:
                    re_delta, re_tid, re_cand = re
                    total = d_jid - pen_jid + re_delta
                    if total < best_total:
                        best_total = total
                        best_chain = (t["id"], cand_jid, e, (re_tid, re_cand))
        return best_chain, best_total

    def chain_pass(max_chains=6):
        """Regret-flavoured pass: for each unassigned job, try direct insertion
        first, else a depth-2 ejection chain.  Accept only strict full-cost
        improvement (already encoded by best_total < -1e-9)."""
        changed = False
        chains_done = 0
        sort_unassigned()
        for jid in list(unassigned):
            if jid not in unassigned:
                continue
            if chains_done >= max_chains:
                break
            job = jobs[jid]
            pen = 150 * job["priority"]
            move, delta = best_insertion(jid)
            if move is not None and (job["emergency"] or delta < pen - 1e-9):
                if apply_insertion(jid, move):
                    changed = True
                    continue
            chain, total = try_chain(jid, pen)
            if chain is not None:
                t_id, cand_jid, e, re = chain
                plan[t_id] = list(cand_jid)
                if jid in unassigned:
                    unassigned.remove(jid)
                if re is not None:
                    re_tid, re_cand = re
                    plan[re_tid] = list(re_cand)
                else:
                    if e not in unassigned:
                        unassigned.append(e)
                changed = True
                chains_done += 1
        return changed

    def local_search(max_rounds=2):
        for _round in range(max_rounds):
            improved = False
            for tid_A in list(plan.keys()):
                tech_A = tech_by_id[tid_A]
                seq_A = list(plan[tid_A])
                for jid in list(seq_A):
                    job = jobs[jid]
                    seq_A_without = [j for j in seq_A if j != jid]
                    cost_A_without = total_cost(tech_A, seq_A_without)
                    cost_A_old = total_cost(tech_A, seq_A)
                    best_delta = 0.0
                    best_move = None
                    for tid_B in plan.keys():
                        if tid_B == tid_A:
                            continue
                        tech_B = tech_by_id[tid_B]
                        if job["skill"] not in tech_B["skills"]:
                            continue
                        seq_B = plan[tid_B]
                        cost_B_old = total_cost(tech_B, seq_B)
                        for pos in range(len(seq_B) + 1):
                            cand = seq_B[:pos] + [jid] + seq_B[pos:]
                            if R(tech_B, cand)["feasible"]:
                                delta = (cost_A_without + total_cost(tech_B, cand)) - (cost_A_old + cost_B_old)
                                if delta < best_delta - 1e-9:
                                    best_delta = delta
                                    best_move = (tid_B, cand, [])
                            else:
                                kept, dropped = custom_drop_to_keep(tech_B, cand, jid)
                                if kept is None:
                                    continue
                                extra = 0
                                for d in dropped:
                                    extra += 150 * jobs[d]["priority"]
                                delta = (cost_A_without + total_cost(tech_B, kept) + extra) - (cost_A_old + cost_B_old)
                                if delta < best_delta - 1e-9:
                                    best_delta = delta
                                    best_move = (tid_B, kept, dropped)
                    if best_move is not None:
                        tid_B, new_seq_B, dropped = best_move
                        plan[tid_A] = optimize_seq(tech_A, seq_A_without)
                        plan[tid_B] = optimize_seq(tech_by_id[tid_B], new_seq_B)
                        for d in dropped:
                            if d not in unassigned:
                                unassigned.append(d)
                        improved = True
                        break
                if improved:
                    break
            if improved:
                continue

            for tid_A in list(plan.keys()):
                tech_A = tech_by_id[tid_A]
                seq_A = list(plan[tid_A])
                for tid_B in list(plan.keys()):
                    if tid_A >= tid_B:
                        continue
                    tech_B = tech_by_id[tid_B]
                    seq_B = list(plan[tid_B])
                    cost_old = total_cost(tech_A, seq_A) + total_cost(tech_B, seq_B)
                    found = False
                    for i, jid_A in enumerate(seq_A):
                        for j, jid_B in enumerate(seq_B):
                            if jobs[jid_B]["skill"] not in tech_A["skills"]:
                                continue
                            if jobs[jid_A]["skill"] not in tech_B["skills"]:
                                continue
                            new_seq_A = seq_A[:i] + [jid_B] + seq_A[i + 1:]
                            new_seq_B = seq_B[:j] + [jid_A] + seq_B[j + 1:]
                            if not (R(tech_A, new_seq_A)["feasible"] and
                                    R(tech_B, new_seq_B)["feasible"]):
                                continue
                            delta = (total_cost(tech_A, new_seq_A) +
                                     total_cost(tech_B, new_seq_B)) - cost_old
                            if delta < -1e-9:
                                plan[tid_A] = optimize_seq(tech_A, new_seq_A)
                                plan[tid_B] = optimize_seq(tech_B, new_seq_B)
                                improved = True
                                found = True
                                break
                        if found:
                            break
                    if found:
                        break
                if improved:
                    break
            if not improved:
                break

    def system_cost():
        c = 0.0
        for tid, seq in plan.items():
            c += total_cost(tech_by_id[tid], seq)
        for jid in unassigned:
            c += 150 * jobs[jid]["priority"]
        return c

    def ruin_recreate(max_rounds=3):
        ranked = sorted(plan.keys(),
                        key=lambda tid: (-total_cost(tech_by_id[tid], plan[tid]), tid))
        for tid in ranked[:max_rounds]:
            if not plan.get(tid):
                continue
            old_sys = system_cost()
            saved_plan = {k: list(v) for k, v in plan.items()}
            saved_unassigned = list(unassigned)

            t = tech_by_id[tid]
            seq = list(plan[tid])
            if len(seq) < 2:
                continue

            def drop_gain(jid, _seq=seq, _t=t):
                idx = _seq.index(jid)
                cand = _seq[:idx] + _seq[idx + 1:]
                return total_cost(_t, _seq) - total_cost(_t, cand)

            candidates = [jid for jid in seq if not jobs[jid]["emergency"]]
            if not candidates:
                continue
            candidates.sort(key=lambda jid: (-drop_gain(jid),
                                             jobs[jid]["priority"], jid))
            k = min(3, len(candidates))
            removed = candidates[:k]
            new_seq = [j for j in seq if j not in removed]
            plan[tid] = optimize_seq(t, new_seq)
            for jid in removed:
                if jid not in unassigned:
                    unassigned.append(jid)

            sort_unassigned()
            for jid in list(unassigned):
                job = jobs[jid]
                move, delta = best_insertion(jid)
                if move is None:
                    continue
                threshold = 150 * job["priority"]
                if job["emergency"] or delta < threshold - 1e-9:
                    apply_insertion(jid, move)

            new_sys = system_cost()
            if new_sys >= old_sys - 1e-9:
                for kk in list(plan.keys()):
                    if kk in saved_plan:
                        plan[kk] = saved_plan[kk]
                unassigned[:] = saved_unassigned

    def shaw_pass(rounds=1, cluster_size=4, num_seeds=6):
        for _r in range(rounds):
            unsched_set = set(unassigned)
            seeds = list(unassigned)
            for tid in sorted(plan.keys()):
                for jid in plan[tid]:
                    seeds.append(jid)
            seen_seeds = set()
            uniq = []
            for jid in seeds:
                if jid not in seen_seeds:
                    seen_seeds.add(jid)
                    uniq.append(jid)
            uniq.sort(key=lambda j: (0 if j in unsched_set else 1,
                                     -jobs[j]["priority"], j))
            seeds = uniq[:num_seeds]
            if not seeds:
                break

            improved_any = False
            for seed in seeds:
                old_sys = system_cost()
                saved_plan = {k: list(v) for k, v in plan.items()}
                saved_unassigned = list(unassigned)

                seed_loc = jobs[seed]["loc"]
                seed_pri = jobs[seed]["priority"]
                seed_ear = jobs[seed]["earliest"]

                def rel(j, _sl=seed_loc, _sp=seed_pri, _se=seed_ear, _us=unsched_set):
                    jl = jobs[j]["loc"]
                    d = abs(jl[0] - _sl[0]) + abs(jl[1] - _sl[1])
                    dpri = abs(jobs[j]["priority"] - _sp)
                    dear = abs(jobs[j]["earliest"] - _se)
                    unp = 0 if j in _us else 1
                    return (d + 3.0 * dpri + 0.1 * dear + 2.0 * unp, j)

                others = [j for j in jobs if j != seed]
                others.sort(key=rel)
                cluster = [seed] + others[:max(0, cluster_size - 1)]

                affected = set()
                for jid in cluster:
                    for tid in list(plan.keys()):
                        if jid in plan[tid]:
                            plan[tid] = [x for x in plan[tid] if x != jid]
                            affected.add(tid)
                    if jid in unassigned:
                        unassigned.remove(jid)

                for tid in affected:
                    t = tech_by_id[tid]
                    if plan[tid]:
                        ns = optimize_seq(t, plan[tid])
                        if ns and R(t, ns)["feasible"]:
                            plan[tid] = ns
                    else:
                        plan[tid] = []

                remaining = list(cluster)
                while remaining:
                    best_jid = None
                    best_score = INF
                    best_mv = None
                    for jid in remaining:
                        mv, dl = best_insertion(jid)
                        if mv is None:
                            continue
                        job = jobs[jid]
                        if job["emergency"]:
                            score = -1e18 + dl
                        else:
                            score = dl - 150.0 * job["priority"]
                        if score < best_score:
                            best_score = score
                            best_jid = jid
                            best_mv = mv
                    if best_jid is None:
                        for jid in remaining:
                            if jid not in unassigned:
                                unassigned.append(jid)
                        break
                    job = jobs[best_jid]
                    if job["emergency"] or best_score < -1e-9:
                        if apply_insertion(best_jid, best_mv):
                            remaining.remove(best_jid)
                            continue
                    for jid in remaining:
                        if jid not in unassigned:
                            unassigned.append(jid)
                    break

                new_sys = system_cost()
                if new_sys >= old_sys - 1e-9:
                    for kk in list(plan.keys()):
                        if kk in saved_plan:
                            plan[kk] = saved_plan[kk]
                    unassigned[:] = saved_unassigned
                else:
                    improved_any = True

            if not improved_any:
                break

    def recover_unassigned(rounds=2, max_eject=1):
        for _r in range(rounds):
            changed = False
            sort_unassigned()
            for jid in list(unassigned):
                if jid not in unassigned:
                    continue
                job = jobs[jid]
                if job["emergency"]:
                    continue
                pen_jid = 150 * job["priority"]
                best = None
                best_delta = -1e-9
                for t in healthy:
                    if job["skill"] not in t["skills"]:
                        continue
                    seq = plan[t["id"]]
                    old_cost = total_cost(t, seq)
                    for pos in range(len(seq) + 1):
                        cand = seq[:pos] + [jid] + seq[pos:]
                        if not R(t, cand)["feasible"]:
                            continue
                        d = total_cost(t, cand) - old_cost - pen_jid
                        if d < best_delta:
                            best_delta = d
                            best = (t["id"], cand, [])
                        if max_eject >= 1:
                            for ej in seq:
                                if jobs[ej]["emergency"]:
                                    continue
                                cand2 = [x for x in cand if x != ej]
                                if not R(t, cand2)["feasible"]:
                                    continue
                                d2 = (total_cost(t, cand2)
                                      + 150 * jobs[ej]["priority"]
                                      - old_cost
                                      - pen_jid)
                                if d2 < best_delta:
                                    best_delta = d2
                                    best = (t["id"], cand2, [ej])
                if best is not None:
                    tid, new_seq, ejected = best
                    t = tech_by_id[tid]
                    new_seq = optimize_seq(t, new_seq)
                    if jid not in new_seq:
                        continue
                    plan[tid] = new_seq
                    if jid in unassigned:
                        unassigned.remove(jid)
                    for ej in ejected:
                        if ej not in unassigned and ej != jid:
                            unassigned.append(ej)
                    for ej in list(ejected):
                        if ej in unassigned:
                            mv, dl = best_insertion(ej)
                            if mv is not None and (
                                jobs[ej]["emergency"]
                                or dl < 150 * jobs[ej]["priority"] - 1e-9
                            ):
                                apply_insertion(ej, mv)
                    changed = True
            if not changed:
                break

    # ---------- phases ----------
    insert_pass()
    chain_pass(6)
    local_search(2)
    recover_unassigned(2)
    shaw_pass(2, 4, 6)
    insert_pass()
    chain_pass(4)
    local_search(2)
    ruin_recreate(3)
    recover_unassigned(2)
    shaw_pass(2, 5, 6)
    local_search(2)
    insert_pass()
    chain_pass(4)
    ruin_recreate(2)
    recover_unassigned(1)
    shaw_pass(2, 4, 5)
    insert_pass()
    chain_pass(4)

    # ---------- force assign remaining emergencies ----------
    sort_unassigned()
    for jid in list(unassigned):
        if not jobs[jid]["emergency"]:
            continue
        move, _ = best_insertion(jid)
        if move is not None:
            apply_insertion(jid, move)

    # ---------- final re-optimize each tech ----------
    for t in healthy:
        tid = t["id"]
        seq = plan[tid]
        if seq:
            new_seq = optimize_seq(t, seq)
            if new_seq and R(t, new_seq)["feasible"]:
                plan[tid] = new_seq

    # ---------- build full plan ----------
    for t in techs:
        if t["sick"]:
            full_plan[t["id"]] = []
        else:
            full_plan[t["id"]] = list(plan.get(t["id"], []))

    # ---------- validation ----------
    seen = set()
    for t in techs:
        if t["sick"]:
            continue
        seq = full_plan[t["id"]]
        clean = []
        for jid in seq:
            if jid in seen:
                continue
            if jid not in jobs:
                continue
            if jobs[jid]["skill"] not in t["skills"]:
                continue
            clean.append(jid)
            seen.add(jid)
        if clean and not R(t, clean)["feasible"]:
            kept, _ = drop_until_feasible(state, t, clean)
            for jid in clean:
                if jid not in kept:
                    seen.discard(jid)
            clean = list(kept)
        full_plan[t["id"]] = clean

    return full_plan
